//! Request-body parity with TS: the Rust chat-completions builder must produce the body the TS
//! `streamOpenAICompletions` request builder produces for the same model, context and options.
//! The cases are generated by `scripts/compat-oracle/bodies.ts` (TS `buildModel` →
//! `streamOpenAICompletions` with an `onPayload` capture); re-run it to refresh.

use serde_json::{json, Value};

use crate::compat::materialize;
use crate::providers::openai_completions::convert::transform_for_request;
use crate::providers::openai_completions::params::build_params;
use crate::providers::openai_completions::{resolve_compat, OpenAICompletionsOptions, ToolChoice};
use crate::types::{CacheRetention, Context, Model, ModelThinkingLevel, StreamOptions};

/// Path of a compat-oracle fixture: `$OMP_COMPAT_ORACLE_DIR` if set, else `<repo
/// root>/target/compat-oracle/` (where `scripts/compat-oracle/*.ts` writes), else the legacy
/// `<repo root>/runs/omp-rust/compat-oracle/`. `None` when the file exists in none of them.
fn oracle_file(name: &str) -> Option<std::path::PathBuf> {
    let repo = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(2)
        .expect("pa-ai lives at <repo>/vendor/pa-ai");
    std::env::var_os("OMP_COMPAT_ORACLE_DIR")
        .map(std::path::PathBuf::from)
        .into_iter()
        .chain([repo.join("target/compat-oracle"), repo.join("runs/omp-rust/compat-oracle")])
        .map(|dir| dir.join(name))
        .find(|path| path.is_file())
}

fn model_of(spec: &Value) -> Model {
    let mut model: Model = serde_json::from_value(spec.clone()).expect("spec parses as a Model");
    materialize(&mut model, None).expect("policy resolves");
    model
}

fn options_of(case: &Value) -> OpenAICompletionsOptions {
    let o = &case["options"];
    let mut base = StreamOptions::default();
    base.max_tokens = o.get("maxTokens").and_then(Value::as_u64);
    base.temperature = o.get("temperature").and_then(Value::as_f64);
    base.session_id = o
        .get("sessionId")
        .and_then(Value::as_str)
        .map(str::to_string);
    let mut opts = OpenAICompletionsOptions::from_base(base);
    opts.reasoning_effort = o
        .get("reasoning")
        .and_then(Value::as_str)
        .and_then(crate::models::thinking_level_from_str)
        .filter(|l| *l != ModelThinkingLevel::Off);
    if o.get("disableReasoning") == Some(&json!(true)) {
        opts.reasoning_enabled = Some(false);
    }
    if let Some(name) = o
        .pointer("/toolChoice/function/name")
        .and_then(Value::as_str)
    {
        opts.tool_choice = Some(ToolChoice::Function {
            name: name.to_string(),
        });
    }
    opts
}

fn rust_body(case: &Value) -> Value {
    let model = model_of(&case["spec"]);
    let context: Context = serde_json::from_value(case["context"].clone()).expect("context parses");
    let options = options_of(case);
    let compat = resolve_compat(&model).expect("compat resolves");
    let transformed = transform_for_request(&model, &context, &compat);
    build_params(
        &model,
        &context,
        &transformed,
        Some(&options),
        &compat,
        CacheRetention::Short,
    )
    .to_value()
}

#[test]
fn rust_body_matches_ts_body_for_every_case() {
    let Some(bodies) = oracle_file("bodies.jsonl") else {
        eprintln!(
            "skipping rust_body_matches_ts_body_for_every_case: bodies.jsonl not found \
             (generate with bun scripts/compat-oracle/bodies.ts, see scripts/compat-oracle/README.md)"
        );
        return;
    };
    let text = std::fs::read_to_string(&bodies).unwrap_or_else(|e| {
        panic!(
            "{}: {e} — regenerate with `bun scripts/compat-oracle/bodies.ts`",
            bodies.display()
        )
    });
    let mut total = 0usize;
    let mut failures: Vec<String> = Vec::new();
    let mut providers = std::collections::BTreeSet::new();
    for line in text.lines().filter(|l| !l.is_empty()) {
        let case: Value = serde_json::from_str(line).expect("case parses");
        if case.get("error").is_some_and(|e| !e.is_null()) {
            continue;
        }
        total += 1;
        let name = case["case"].as_str().unwrap_or("?").to_string();
        providers.insert(case["spec"]["provider"].as_str().unwrap_or("?").to_string());
        let got = rust_body(&case);
        let want = &case["body"];
        if &got != want {
            let mut diffs = Vec::new();
            let (g, w) = (got.as_object().unwrap(), want.as_object().unwrap());
            let keys: std::collections::BTreeSet<_> = g.keys().chain(w.keys()).collect();
            for k in keys {
                if g.get(k) != w.get(k) {
                    diffs.push(format!(
                        "{k}: rust={} ts={}",
                        g.get(k).map_or("<absent>".into(), ToString::to_string),
                        w.get(k).map_or("<absent>".into(), ToString::to_string)
                    ));
                }
            }
            failures.push(format!("{name}: {}", diffs.join(" | ")));
            let _ = &name;
        }
    }
    eprintln!(
        "body parity: {total} cases over {} providers, {} mismatches",
        providers.len(),
        failures.len()
    );
    for f in failures.iter().take(25) {
        eprintln!("  MISMATCH {}", &f[..f.len().min(420)]);
    }
    assert!(
        failures.is_empty(),
        "{} of {total} request bodies differ from TS",
        failures.len()
    );
}
